      "2)",
      "Mélangez le tant-pour-tant avec la première pesée de blancs d’œufs, l’huile, les colorants et la coco râpée. Faites cuire le sucre et l’eau à 118°C. Lorsque le sucre est à 115°C, démarrez les blancs d’œufs. Une fois montés, mais pas trop fermes, enclenchez le batteur en 2ème vitesse, versez le sucre cuit. Laissez refroidir à 50°C environ, retirez la cuve du batteur. Incorporez la meringue dans le mélange tant-pour-tant, blancs crus, huile, colorants et coco râpée ; faites retomber l’appareil et dressez.",
      "NB : Suivant la technique du dressage, il faut plus ou moins faire retomber l’appareil. Pour l’utilisation à la dresseuse automatique, préférez une masse retombée au minimum, alors que le pochage manuel s’effectue avec l’appareil bien retombé.",
      "Dressage et cuisson",
      "Noix de coco râpée médium (Navimpex Réf :)",
      "A l’aide d’une  poche munie d’une douille n°11 ou de la dresseuse automatique, sur une plaque recouverte de papier siliconé, dressez les coques de macarons à la taille désirée. Saupoudrez légèrement la moitié des coques de noix de coco râpée. Laissez « croûter » à température ambiante pendant environ 30 minutes. Cuisson en four à air ventilé : 165°C pendant 10 à 11 minutes et pendant 15 minutes pour les individuels. Cuisson toujours buée ouverte. Débarrassez les feuilles sur grilles et laissez refroidir.",
      "Assemblage des macarons",
      "Gelée de mangue",
      "Retournez les feuilles de macarons sur grille pour décollez les coques et les rangez. A l’aide d’un pulvérisateur, humidifiez légèrement les coques. A l’aide d’une poche munie d’une douille n°11, garnissez généreusement la moitié des coques de crème caramel au beurre demi-sel. Posez un carré de gelée de mangue et recouvrez en prenant soin d’assortir les tailles des coques.",
      "Affinage & stockage",
      "Deux possibilités s’offrent à nous à ce stade, soit une conservation et transport en froid négatif, soit en froid positif.",
      "1) Stockage en froid négatif : rangez les grilles sans les couvrir, dans un réfrigérateur pendant 2 heures. Rangez les macarons en boîtes plastiques hermétiques, filmez les boites et glissez-les au surgélateur pendant 2 heures. Stockez au congélateur à –18°C.",
      "2) Stockage en froid positif : rangez les grilles sans les couvrir, dans un réfrigérateur avec une hygrométrie oscillant entre 70 et 80 % d’humidité, pendant au moins 24 heures, mais 36 heures sont préférables. Rangez les macarons en boîtes plastiques hermétiques et stockez-les au réfrigérateur.",
