      "Tamisez ensemble le sucre glace et la poudre d'amande. Fouettez les blancs en neige ferme dans une grande terrine ; colorez-les avec le colorant jaune d’œuf et l’arôme café. Versez très rapidement, en pluie, le mélange sucre-amande dans les blancs, en les ramenant du milieu vers les bords, à l'aide d'une corne, sans les tourner ni les casser, tout en faisant tourner la terrine. La pâte, lorsqu'elle est homogène, elle est presque coulante : les blancs - qui n'ont pas été sucrés pour ne pas donner un goût de meringue aux macarons - sont un peu retombés ; ce n'est pas un défaut, bien au contraire, car cela évitera que les macarons, à la cuisson, ne forment une petite coque sèche comme une meringue.",
