      "Dans la cuve d'un batteur munie du fouet, versez les blancs et fouettez-les à vitesse moyenne, jusqu'à ce qu'ils doublent de volume, en ajoutant un tiers de la première pesée de sucre et continuez de les fouetter jusqu'à ce qu'ils deviennent très fermes, très lisses et très brillants en ajoutant le reste de la première pesée de sucre. Détachez la cuve du batteur et incorporez le reste du sucre en pluie et les colorant en soulevant les blancs avec une spatule et en les travaillant le moins possible.",
