      "Garnissez une poche plastique avec de la meringue, dressez la meringue au tiers de la hauteur dans les moules Flexipan 7 cm en forme de dôme, puis à l’aide d’une cuillère à entremet chemisez les dômes. Raclez l’excédant de meringue sur le dessus, à l’aide d’une palette. Idéalement, faites sécher les coques de meringue à l’étuve ou au four à 60°C pendant plusieurs heures. Lorsqu’elles sont bien sèchent, démoulez sur une plaque recouverte d’une feuille de papier cuisson et mettez au four à 110°C pendant 20 minutes. Remettez les coques dans les moules Flexipan 7 cm en forme de dôme et pulvérisez avec le mélange à pulvériser ivoire. Démoulez sur une plaque avec une feuille anti dérapante et stockez à l’abri de l’humidité.",
